#include <graphics.h> #include <conio.h> #include <math.h>  int main() {     int gd = DETECT, gm;     int x1 = 100, y1 = 100;     int x2 = 150, y2 = 100;     int x3 = 125, y3 = 50;     int x, y, ch;     float a, s;      initgraph(&gd, &gm, "C:\\Turboc3\\BGI");      do     {         cleardevice();          line(x1, y1, x2, y2);         line(x2, y2, x3, y3);         line(x3, y3, x1, y1);          outtextxy(10, 10, "1. Translation");         outtextxy(10, 30, "2. Scaling");         outtextxy(10, 50, "3. Rotation");         outtextxy(10, 70, "4. Reflection");         outtextxy(10, 90, "5. Shearing");         outtextxy(10, 110,"6. Exit");          ch = getch();          if (ch == '1')         {             x1 += 20; y1 += 20;             x2 += 20; y2 += 20;             x3 += 20; y3 += 20;         }         else if (ch == '2')         {             x1 = x1 * 2; y1 = y1 * 2;             x2 = x2 * 2; y2 = y2 * 2;             x3 = x3 * 2; y3 = y3 * 2;         }         else if (ch == '3')         {             a = 45 * 3.14159 / 180;              x = x1; y = y1;             x1 = x * cos(a) - y * sin(a);             y1 = x * sin(a) + y * cos(a);              x = x2; y = y2;             x2 = x * cos(a) - y * sin(a);             y2 = x * sin(a) + y * cos(a);              x = x3; y = y3;             x3 = x * cos(a) - y * sin(a);             y3 = x * sin(a) + y * cos(a);         }         else if (ch == '4')         {             y1 = 480 - y1;             y2 = 480 - y2;             y3 = 480 - y3;         }         else if (ch == '5')         {             x1 = x1 + y1;             x2 = x2 + y2;             x3 = x3 + y3;         }      } while (ch != '6');      closegraph();     return 0; } 